sys_variable_value.value:
(function execute(inputs, outputs) {
    var logger = new x_snc_aegis.AEGISDecisionLogger();
    logger.logAction(
        'Workflow',
        'STAGE_TRANSITION',
        null,
        inputs.trigger_record.sys_id.toString(),
        'JR submitted by: ' + inputs.trigger_record.requested_by.getDisplayValue() +
            ' | Role: ' + inputs.trigger_record.role_title.toString(),
        'JR APPROVED by manager',
        null,
        'Manager approval required before JD generation'
    );
})(inputs, outputs);

